-- Probe D2: force the no-data path in a real procedure, with ROLLBACK in handlers
CREATE OR REPLACE PROCEDURE probe_d2(p_force boolean DEFAULT true) LANGUAGE plpgsql AS $proc$
DECLARE
    v_has_data numeric := 0;
BEGIN
    BEGIN
        IF p_force THEN
            RAISE EXCEPTION 'no data available for monthly report'
                USING ERRCODE = 'P0002';
        END IF;
        RAISE NOTICE 'D2: normal path';
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            RAISE NOTICE 'D2: caught no_data_found, rolled back (SQLSTATE %)', SQLSTATE;
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE NOTICE 'D2: caught others, rolled back (SQLSTATE %)', SQLSTATE;
    END;
    COMMIT;
    RAISE NOTICE 'D2: reached commit';
END;
$proc$;

CALL probe_d2(true);
CALL probe_d2(false);

-- Probe D3: OTHERS branch that re-raises like the original
CREATE OR REPLACE PROCEDURE probe_d3() LANGUAGE plpgsql AS $proc$
BEGIN
    BEGIN
        RAISE EXCEPTION 'boom' USING ERRCODE = 'P0003';
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
        WHEN OTHERS THEN
            ROLLBACK;
            RAISE;
    END;
    COMMIT;
END;
$proc$;
CALL probe_d3();
EOF

