    BEGIN
        RAISE EXCEPTION 'boom' USING ERRCODE = 'P0002';
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            ROLLBACK;
            RETURN;
    END;
    COMMIT;
    RAISE NOTICE 'H: this should NOT print';
END;
$proc$;
CALL probe_h();
RAISE NOTICE 'H: call completed normally';
EOF

